Plan (no files created yet):

**Facts from reading the code**
- `createSession(userId)` is the only "start a session" primitive; `login` in `src/api/routes.ts:11` calls exactly `createSession(user.id)` after authenticating. So the refresh equivalent is `createSession(existing.userId)` — no need to import `login` (which would create an auth→api dependency and a cycle risk).
- Conventions: `.ts` extensions in import specifiers, 2-space indent, double quotes, `/** … */` one-line doc comments, `assert` from `node:assert/strict`.

**1. New file `src/auth/refresh.ts`**

```ts
import { createSession, getSession, revokeSession, type Session } from "./session.ts";

/**
 * Replace a live session with a fresh one for the same user.
 * Returns undefined if the token has no live session.
 */
export function refreshSession(token: string): Session | undefined {
  const current = getSession(token);
  if (!current) return undefined;
  revokeSession(token);
  return createSession(current.userId);
}
```

**2. New file `test/refresh.test.ts`**

```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createSession, getSession, resetSessions, revokeSession } from "../src/auth/session.ts";
import { refreshSession } from "../src/auth/refresh.ts";

beforeEach(() => resetSessions());

test("refreshSession returns undefined for an unknown token", () => {
  assert.equal(refreshSession("nope"), undefined);
});

test("refreshSession revokes the old token and returns a new session for the same user", () => {
  const old = createSession("u_1");
  const fresh = refreshSession(old.token);
  assert.ok(fresh);
  assert.equal(fresh.userId, "u_1");
  assert.notEqual(fresh.token, old.token);
  assert.equal(getSession(old.token), undefined);
  assert.equal(getSession(fresh.token)?.userId, "u_1");
});

test("refreshSession leaves other sessions of the same user untouched", () => {
  const a = createSession("u_1");
  const b = createSession("u_1");
  refreshSession(a.token);
  assert.equal(getSession(b.token)?.userId, "u_1");
});

test("a refreshed token cannot itself be refreshed twice for the same session", () => {
  const old = createSession("u_2");
  const fresh = refreshSession(old.token);
  assert.ok(fresh);
  assert.equal(refreshSession(old.token), undefined);
  const again = refreshSession(fresh.token);
  assert.ok(again);
  assert.equal(getSession(fresh.token), undefined);
});
```

**3. Verify:** `npm test` and `npm run typecheck`.

One judgment call to flag: the spec says "start it exactly the way `login` does", but `login` also calls `authenticate(email, password)` first — that needs credentials, which a refresh has no access to. I read "exactly the way" as the session-creation step (`createSession(user.id)`), not re-authentication. Say the word if you want `refreshSession` to take credentials too, or if the signature should stay as specified.
